{"onClick":"() => {
                    exportMutation.mutate({
                      scope: "customer-orders",
                      customerId: customer.id,
                      purpose: "CUSTOMER_ORDER_HISTORY_EXPORT",
                      filters: {
                        search: searchQuery,
                        orderStatus: ORDER_STATUS_EXPORT[statusFilter],
                      },
                    })
                  }","disabled":"!capabilities.canExport || exportMutation.isPending"}

{"disabled":"!capabilities.canOpenSales","onClick":"() => {
                    info("Create Order", `Redirecting to create order for ${customer.name}`)
                    router.push(localizedHref(`/dashboard/sales`))
                  }"}

{"disabled":"!capabilities.canViewReceivables","onClick":"() => {
                          info("Open Receivables", "Opening the finance receivables workspace")
                          router.push(localizedHref("/dashboard/finance/receivables"))
                        }"}

{"disabled":"!capabilities.canOpenSales","onClick":"() => {
                          info("Open Sales", `Redirecting to create first order for ${customer.name}`)
                          router.push(localizedHref(`/dashboard/sales`))
                        }"}

{"onCheckedChange":"(checked) => {
                          field.onChange(checked)
                          if (checked && openingStockEnabled) {
                            setOpeningStockEnabled(false)
                            form.setValue('initialInventory', undefined, { shouldDirty: true, shouldValidate: true })
                            info("Opening Stock Cleared", "Receive serial-tracked stock after creating the item so each serial number can be recorded.")
                          }
                        }"}

{"disabled":"locations.length === 0 || Boolean(isSerialTracked)","onCheckedChange":"(checked) => {
                        setOpeningStockEnabled(checked)
                        form.setValue(
                          'initialInventory',
                          checked
                            ? {
                                locationId: "",
                                quantity: 1,
                                unitCost: Number(form.getValues('costPrice')) || 0,
                                notes: "",
                                referenceNumber: "",
                              }
                            : undefined,
                          { shouldDirty: true, shouldValidate: true },
                        )
                      }"}

{"onUploadStart":"{() => {
                    setIsImageUploading(true)
                  }}","onUploadComplete":"{() => {
                    setIsImageUploading(false)
                  }}","onUploadError":"{() => {
                    setIsImageUploading(false)
                    error("Upload Failed", "The product image could not be uploaded. Please try again.")
                  }}"}

{"onUploadStart":"{() => {
                      setIsImageUploading(true)
                      setSaveError(null)
                    }}","onUploadComplete":"{() => setIsImageUploading(false)}","onUploadError":"{() => {
                      setIsImageUploading(false)
                      setSaveError("The replacement image upload failed. The current item image is unchanged.")
                    }}"}

{"type":""number"","disabled":"updateLine.isPending","onChange":"(event) => {
                                  const { value } = event.target
                                  const parsedQuantity = Number(value)
                                  const nextValue = quantityOnHand !== null && Number.isFinite(parsedQuantity) && parsedQuantity > quantityOnHand
                                    ? String(quantityOnHand)
                                    : value
                                  setQuantityDrafts((current) => ({ ...current, [line.id]: nextValue }))
                                }","onBlur":"() => {
                                  void commitQuantityDraft(line.id)
                                }","onKeyDown":"(event) => {
                                  if (event.key === "Enter") {
                                    event.preventDefault()
                                    event.currentTarget.blur()
                                  }
                                }"}

{"onChange":"(event) => {
                                const method = event.target.value as TenderMethod
                                updateTenderLine(line.id, {
                                  method,
                                  paymentTransactionId: isElectronicTenderMethod(method)
                                    ? line.paymentTransactionId
                                    : "",
                                })
                              }"}

{"onValueChange":"(value) => {
                    field.onChange(value)
                    // Preserve an existing quoted cost. A newly added line can use the current cost suggestion.
                    if (!line.itemId) form.setValue(`lines.${index}.unitPrice`, items.find((item) => item.id === value)?.costPrice ?? 0, { shouldDirty: true })
                  }","disabled":"busy || locked"}

{"type":""button"","onClick":"() => {
                            const newReceiveItems: Record<string, ReceiveItemDraft> = {}
                            purchaseOrder.lines?.forEach(line => {
                              const orderedQuantity = toNumber(line.orderedQuantity)
                              const maxAllowed = orderedQuantity - toNumber(line.receivedQuantity)
                              if (maxAllowed > 0) {
                                newReceiveItems[line.id] = {
                                  ...receiveItems[line.id],
                                  quantity: orderedQuantity,
                                  received: maxAllowed
                                }
                              }
                            })
                            setReceiveItems(newReceiveItems)
                            success(
                              "All Items Selected",
                              "All available quantities have been set for receiving",
                              { duration: 3000, sound: false }
                            )
                          }"}

{"type":""button"","onClick":"() => {
                            setReceiveItems({})
                            info(
                              "Quantities Cleared",
                              "All receive quantities have been reset to zero",
                              { duration: 3000, sound: false }
                            )
                          }"}

{"type":""number"","onChange":"(e) => {
                                            const inputValue = parseInt(e.target.value) || 0
                                            const orderedQuantity = toNumber(line.orderedQuantity)
                                            const maxAllowed = orderedQuantity - toNumber(line.receivedQuantity)

                                            // Hard limit enforcement
                                            const finalValue = Math.min(Math.max(0, inputValue), maxAllowed)

                                            // Show notification if user tried to exceed limit
                                            if (inputValue > maxAllowed && inputValue > 0) {
                                              warning(
                                                "Quantity Limited",
                                                `Maximum ${maxAllowed} units can be received for ${line.item?.name || 'this item'}. Input automatically adjusted.`,
                                                { duration: 5000, sound: true }
                                              )
                                            }

                                            setReceiveItems(prev => ({
                                              ...prev,
                                              [line.id]: {
                                                ...prev[line.id],
                                                quantity: orderedQuantity,
                                                received: finalValue
                                              }
                                            }))
                                          }","onKeyDown":"(e) => {
                                            // Allow: backspace, delete, tab, escape, enter
                                            if ([8, 9, 27, 13, 46].indexOf(e.keyCode) !== -1 ||
                                              // Allow: Ctrl+A, Ctrl+C, Ctrl+V, Ctrl+X
                                              (e.keyCode === 65 && e.ctrlKey === true) ||
                                              (e.keyCode === 67 && e.ctrlKey === true) ||
                                              (e.keyCode === 86 && e.ctrlKey === true) ||
                                              (e.keyCode === 88 && e.ctrlKey === true) ||
                                              // Allow: home, end, left, right
                                              (e.keyCode >= 35 && e.keyCode <= 39)) {
                                              return
                                            }
                                            // Ensure that it is a number and stop the keypress
                                            if ((e.shiftKey || (e.keyCode < 48 || e.keyCode > 57)) && (e.keyCode < 96 || e.keyCode > 105)) {
                                              e.preventDefault()
                                              info(
                                                "Numbers Only",
                                                "Please enter numeric values only",
                                                { duration: 2000, sound: false }
                                              )
                                            }
                                          }","onBlur":"(e) => {
                                            // Additional validation on blur to ensure clean state
                                            const inputValue = parseInt(e.target.value) || 0
                                            const orderedQuantity = toNumber(line.orderedQuantity)
                                            const maxAllowed = orderedQuantity - toNumber(line.receivedQuantity)
                                            const finalValue = Math.min(Math.max(0, inputValue), maxAllowed)

                                            if (inputValue !== finalValue) {
                                              setReceiveItems(prev => ({
                                                ...prev,
                                                [line.id]: {
                                                  ...prev[line.id],
                                                  quantity: orderedQuantity,
                                                  received: finalValue
                                                }
                                              }))
                                            }
                                          }"}

{"type":""button"","onClick":"() => {
                                            const orderedQuantity = toNumber(line.orderedQuantity)
                                            const maxAllowed = orderedQuantity - toNumber(line.receivedQuantity)
                                            setReceiveItems(prev => ({
                                              ...prev,
                                              [line.id]: {
                                                ...prev[line.id],
                                                quantity: orderedQuantity,
                                                received: maxAllowed
                                              }
                                            }))
                                          }","disabled":"(toNumber(line.orderedQuantity) - toNumber(line.receivedQuantity)) === 0"}

{"type":""text"","onChange":"(event) =>
                                                  setReceiveItems((prev) => ({
                                                    ...prev,
                                                    [line.id]: {
                                                      ...prev[line.id],
                                                      quantity: toNumber(line.orderedQuantity),
                                                      received: prev[line.id]?.received || 0,
                                                      batchNumber: event.target.value,
                                                    },
                                                  }))"}

{"type":""date"","onChange":"(event) =>
                                                  setReceiveItems((prev) => ({
                                                    ...prev,
                                                    [line.id]: {
                                                      ...prev[line.id],
                                                      quantity: toNumber(line.orderedQuantity),
                                                      received: prev[line.id]?.received || 0,
                                                      expiryDate: event.target.value,
                                                    },
                                                  }))"}

{"onClick":"() => {
                  archiveOpenerSupplierIdRef.current = supplier.id
                  archiveOpenerRef.current = Array.from(
                    document.querySelectorAll<HTMLButtonElement>(
                      "[data-supplier-actions-id]",
                    ),
                  ).find(
                    (candidate) =>
                      candidate.dataset.supplierActionsId === supplier.id,
                  ) ?? null
                  setArchiveTarget(supplier)
                }"}

